                        'hendricks' => ['National Endowment for the Arts, Jon Hendricks', 'https://www.arts.gov/honors/jazz/jon-hendricks'],
                        'ecu' => ['East Carolina University Libraries, Sing a Song of Basie, the recording note', 'https://librarycatalog.ecu.edu/catalog/4791385'],
                        'kth' => ['KTH Royal Institute of Technology, "Ensemble swing", summarising Music Perception (2002)', 'https://www.speech.kth.se/music/performance/Texts/ensemble_swing.htm'],
                        'datseris' => ['Scientific Reports (2019), timing fluctuations and the swing feel', 'https://doi.org/10.1038/s41598-019-55981-3'],
                        'donnay' => ['PLoS ONE (2014), trading fours in a brain scanner', 'https://doi.org/10.1371/journal.pone.0088665'],
                        'cutting' => ['Empirical Musicology Review (2019), blue notes measured', 'https://doi.org/10.18061/emr.v13i1-2.6316'],
                        'przysinda' => ['Brain and Cognition (2017), jazz musicians and unexpected chords', 'https://pubmed.ncbi.nlm.nih.gov/29028508/'],
