            'learn-your-choir-part' => [
                'group' => 'harmony',
                'app' => 'choir-part',
                'name' => 'Learn your part for rehearsal',
                'summary' => 'Hear your line, find your first note, fix the hard bars, and walk in ready.',
                'title' => 'Learn your choir part: a free course',
                'description' => 'Learn your choir part at home and walk into rehearsal knowing it: find your first note, fix the hard bars, then sing it through without the guide. Free.',
                'headline' => 'Walk into rehearsal knowing your part.',
                'lead' => 'The way a choir member learns a part over a week, in short lessons: hear your line inside the whole sound, find your first note from the pianist\'s chord, fix the hard bars, put the guide down, and sing it through without stopping.',
                'learn' => [
                    'Your own part, soprano, alto, tenor or bass, in your range',
                    'Hearing your own line inside all four parts',
                    'Finding your first note from the pianist\'s chord',
                    'Following your line on a stave',
                    'Fixing a hard bar: slow, then faster',
                    'Singing with the guide, then without it',
                    'A run-through that doesn\'t stop, like the real thing',
                ],
                'measures' => 'Your notes on pitch, line by line: first with the guide, then on your own with the other parts. You pick your part, soprano, alto, tenor or bass, on one real four-part piece set in your own range, and the last lesson shows you how to learn any song\'s part the same way.',
                'scoring' => ['game' => 'Up to three stars for the notes on pitch, and XP, with challenges along the way.', 'serious' => 'The same take says it plainly, like "21 of 24 notes on pitch", with no stars or XP.'],
                'safety' => [
                    'Sing at an easy, medium-soft volume, not a whisper.',
                    'If a note sits too high or low, sing it lightly, never louder.',
                    'Stop if anything tightens or hurts.',
                ],
                'songs' => [['O Come, All Ye Faithful', 'Latin hymn, 18th century; English words 1841; public domain. The four-part setting is our own.']],
            ],
            // Backing vocals (the courses lead, content d47e700): the sound behind the song. No living singer or group named.
            'backing-vocals' => [
                'group' => 'harmony',
                'name' => 'Backing vocals',
                'summary' => 'The sound behind the song: pads, doo-wop and answers.',
                'title' => 'Backing vocals: a free course for singers',
                'description' => 'Learn backing vocals: soft pads under the lead, doo-wop parts, and answers that fill the gaps, stacked over your own takes. A free course, in short lessons.',
                'headline' => 'The sound behind the song.',
                'lead' => 'Sing the parts that sit behind a lead: a soft "oo" pad that moves with the chords, doo-wop figures, and answers in the lead\'s gaps, then put them behind a real song.',
                'learn' => [
                    'Oohs and aahs: a held pad under the lead, moving with the chords, everyone stopping together',
                    'Doo-wop: "doo-wah" and "bop" figures, three parts stacked over your own takes',
                    'Answers: filling the lead\'s gaps and coming back in on time',
                    'Behind a real song: a pad, then answers, then three backing parts of your own, kept as a song',
                ],
                'measures' => 'Your notes on pitch, and in some lessons your cut-offs, when you come back in, and whether your answers land on the beat. Volume and blend aren\'t scored: the course asks you to listen, and in your headphones, could you hear the lead over yourself? Headphones on for every lesson: through a speaker, the lead and your earlier takes rest while you sing.',
                'scoring' => ['game' => 'Up to three stars for the notes on pitch, and in the answers on the beat, and XP.', 'serious' => 'The same take says it plainly, like "21 of 24 notes on pitch" or "93% on pitch and time", with no stars or XP.'],
                'safety' => ['Easy volume, softer than the tune.', 'Stop if anything tightens or hurts.'],
                'songs' => [['Shenandoah', 'Traditional, public domain'], ['Swing Low, Sweet Chariot', 'Spiritual, public domain'], ['Michael, Row the Boat Ashore', 'Traditional, public domain'], ['Home on the Range', 'Traditional, 1870s, public domain'], ['Amazing Grace', 'Public domain hymn (words 1779, tune 1829)'], ['The doo-wop lead and every backing part', 'Written for the course']],
